  "help.account": "Account applications and approval", "help.apply": "Account application", "help.applyText": "1. Select Apply for access on the login page. 2. Retrieve the email verification code. 3. Submit the application for approval.", "help.approval": "Registration approval", "help.approvalText": "In Admin, set the applicant's role and group, then approve or reject the application.", "help.switch": "Registration switch", "help.switchText": "Administrators can suspend self-service registration. While closed, verification-code and application requests are rejected.",
  "help.security": "Administration and account security", "help.transfer": "Administration transfer", "help.transferText": "1. Select a successor and transfer mode. 2. Enter your current password. 3. Confirm the transfer.", "help.coAdmin": "Co-administrator", "help.coAdminText": "Promotes the successor while retaining the current administrator for operational resilience.", "help.fullTransfer": "Full transfer", "help.fullTransferText": "Promotes the successor, then demotes the current administrator. The system never permits removal of the final administrator.",
  "help.dashboard": "Dashboard", "help.kpi": "KPI cards", "help.kpiText": "Review the organization overview and current-quarter KR completion, then open a project for details.", "help.license": "License expiry alerts", "help.licenseText": "QA members and administrators can see licenses expiring within 90 days.", "help.risk": "Risk badge", "help.riskText": "Green, amber, and red reflect AI risk analysis. Run the analysis again from the project overview.",
  "help.projects": "Projects and tasks", "help.newProject": "New project", "help.newProjectText": "1. Select a group and visibility. 2. Select a template. 3. Create the project.", "help.okr": "OKR", "help.okrText": "Switch quarters, set the objective, create and reorder KRs; automatic progress includes KRs.", "help.views": "Kanban, list, calendar, and Gantt", "help.viewsText": "1. Open the Tasks tab. 2. Select a view. 3. Open a task drawer. History events use secondary dots in the calendar and hollow dim-gold diamonds in Gantt, and never count toward automatic progress.", "help.drawer": "Task drawer", "help.drawerText": "Choose prerequisites first. The start date is suggested as the day after their latest due date while preserving an existing duration. A manually edited start date is never overwritten, and dates are written only after you select Save task.", "help.progressLinks": "Progress-link suggestions", "help.progressLinksText": "After publishing progress, AI may suggest completing or creating tasks, adding future milestones, creating history events for past completed facts, or setting dates on existing tasks. Every item starts unchecked; review it, edit titles or dates when needed, and select Apply selected. A past completed fact is suggested only as a history event, never as a milestone or progress input. You can disable suggestions in Profile. All timestamps are displayed in Taipei time.", "help.schedule": "AI schedule suggestions", "help.scheduleText": "1. Generate suggestions. 2. Review the dates. 3. Apply all suggestions.",
  "help.qa": "QA and regulatory", "help.registry": "Expiry registry", "help.registryText": "Use the QA tab to record license and system expiry dates and see alerts based on days remaining.", "help.ccr": "CCR", "help.ccrText": "Advance change controls only through valid states. Every step retains its history, and validity confirmation creates a to-do.", "help.regwatch": "Regulatory Watch", "help.regwatchText": "Everyone can browse and filter published entries. RA/PV employees and administrators can create, edit, and delete them. Entries are sorted newest-first by announced date.", "help.regAi": "Regulatory AI import", "help.regAiText": "1. Open AI Import. 2. A single announcement becomes one record; use multiple-announcement mode only for different announced dates or titles. 3. Paste text, or combine up to five .txt/text-layer .pdf files (10 MB each, 25 MB total). 4. AI always uses the announced/issued date; effective dates go in key points and dates over 90 days ahead are flagged. 5. Comparison tables receive a separate old-to-new summary. 6. Edit and confirm; duplicate keys are skipped and attachments can be downloaded individually. Paste text for scanned PDFs.", "help.tfdaReview": "TFDA automatic fetch and review", "help.tfdaReviewText": "The daily job fetches the TFDA RSS feed first; RA/PV employees and administrators can also fetch immediately. New announcements stay as drafts and notify reviewers. Open Pending to inspect full key points; edit, approve, or delete one draft, select several for batch approval or deletion, or confirm Approve all. Other employees and interns cannot see drafts before approval.",
  "help.collaboration": "Collaboration", "help.mention": "@mentions", "help.mentionText": "1. Type @ in a comment. 2. Select a person. 3. Submit the comment to notify them.", "help.files": "Files", "help.filesText": "Drag or select files to upload; download or delete them at project or task level.", "help.automation": "Automation", "help.automationText": "1. Select a trigger. 2. Select an action. 3. Disable the rule later if needed.",
  "help.personal": "Personal work", "help.todos": "To-dos", "help.todosText": "Link a to-do to a project; completing it advances automatic project progress.", "help.notifications": "Notifications", "help.notificationsText": "The badge shows unread items. Open a notification to jump to the relevant project or task.", "help.timeline": "Timeline", "help.timelineText": "Compare visible projects in group lanes, filter by group, and expand task bars.", "help.reports": "Group weekly and monthly reports", "help.reportsText": "Select a group and period. Standard reports exclude confidential projects; only administrators can include them.", "help.font": "Text size", "help.fontText": "Choose Standard 17px or Large 18.5px in Profile; the browser remembers your preference.", "help.languageTheme": "Language and theme", "help.languageThemeText": "Use the navigation controls to switch between Traditional Chinese and English, and between dark and light themes. This browser remembers both preferences.", "help.admin": "Administration", "help.import": "Batch import", "help.importText": "Paste JSON, preview record counts in the browser, confirm the import, and review created/updated/skipped totals. See IMPORT.md for the format.",
  "files.title": "Shared files", "files.uploading": "Uploading…", "files.drop": "Drop a file here or choose one (25 MB maximum)", "files.empty": "No attachments", "files.uploadFailed": "Upload failed", "files.deleteConfirm": "Delete “{name}”?",
